import { ActionDefinition } from '../../../Action'
import { StringColumn, DocumentIdColumn, IntegerColumn, RecordsColumn } from '../../../../db'

export const getAttachmentsOnRecord = ActionDefinition({
    $id: '082e70db0f4273003788001ea8767e02',
    name: 'Get Attachments on Record',
    description:
        'Returns a list and count of the attachments associated with the provided source record. Use flow logic or scripting to process individual attachments. Returns an error if server-side validation such as ACLs, business rules, or data policies prevent the look up.',
    category: 'a20738df9363130079b5925cf67ffb74',
    inputs: {
        file_name: StringColumn({
            label: 'File Name',
            maxLength: 8000,
        }),
        source_record: DocumentIdColumn({
            label: 'Source Record',
            mandatory: true,
            dependent: 'sys_attachment',
            tableReference: true,
        }),
    },
    outputs: {
        parameter: RecordsColumn({
            label: 'Attachment List',
            referenceTable: 'sys_attachment',
        }),
        parameter1: IntegerColumn({
            label: 'Count',
            maxLength: 4000,
        }),
    },
})
